import { z } from "zod";
import {
  MEAL_TYPES,
  WEEKDAYS,
  mealPlanSchema,
  type MealPlan,
  type MealTypeValue,
  type PlannedDay,
  type PlannedFood,
  type PlannedMacros,
  type PlannedMeal,
} from "./mealPlan.js";

/**
 * The plan format generated by the Claude Fitness project (snake_case): meal slots with times, days
 * as a list, meals keyed by slot id, items with food/quantity/unit/note.
 * - schema_version 1: as above.
 * - schema_version 2: adds `grams` on items, per-meal `macros` (null on free meals),
 *   `alternative_macros`, `day_macros` and `macros_info`.
 * Intake converts it to its own MealPlan on upload. Unknown fields (targets, shopping_list,
 * day_macros, alternative_macros…) are ignored.
 *
 * Optional extension understood by Intake: a `macros` object on each meal (see docs/meal-plan-format.md),
 * so that "Mangiato come previsto" logs complete values; and `valid_from` (defaults to `updated`).
 */

const nullable = <T extends z.ZodType>(schema: T) => schema.nullable().optional();

const cfItemSchema = z.looseObject({
  food: z.string().trim().min(1),
  quantity: nullable(z.number().positive()),
  unit: nullable(z.string()),
  note: nullable(z.string()),
  /** schema_version 2: the item's weight in grams, also for units such as "pz" or "fette" */
  grams: nullable(z.number().nonnegative()),
});

const cfMacrosSchema = z.looseObject({
  kcal: z.number().nonnegative(),
  protein_g: z.number().nonnegative(),
  carbs_g: z.number().nonnegative(),
  fat_g: z.number().nonnegative(),
  fiber_g: z.number().nonnegative(),
  sugar_g: nullable(z.number().nonnegative()),
  added_sugar_g: nullable(z.number().nonnegative()),
  saturated_fat_g: nullable(z.number().nonnegative()),
  sodium_mg: nullable(z.number().nonnegative()),
  caffeine_mg: nullable(z.number().nonnegative()),
});

const cfMealSchema = z.looseObject({
  description: nullable(z.string()),
  items: z.array(cfItemSchema).default([]),
  alternative: nullable(z.array(cfItemSchema)),
  free: nullable(z.boolean()),
  sweet: nullable(z.boolean()),
  family_friendly: nullable(z.boolean()),
  macros: nullable(cfMacrosSchema),
});

const cfDaySchema = z.looseObject({
  day: z.enum(WEEKDAYS),
  label: nullable(z.string()),
  note: nullable(z.string()),
  expected_protein_g: nullable(z.number().nonnegative()),
  tags: nullable(z.array(z.string())),
  free_meals: nullable(z.array(z.string())),
  meals: z.record(z.string(), cfMealSchema),
});

export const claudeFitnessPlanSchema = z.looseObject({
  schema_version: z.union([z.literal(1), z.literal(2)]),
  updated: z.iso.date(),
  valid_from: nullable(z.iso.date()),
  meal_slots: z
    .array(
      z.looseObject({
        id: z.string().min(1),
        label: z.string().trim().min(1),
        time: nullable(z.string().regex(/^([01]\d|2[0-3]):[0-5]\d$/, "time must be HH:MM (24-hour)")),
      }),
    )
    .min(1),
  free_meals: nullable(z.array(z.looseObject({ day: z.enum(WEEKDAYS), meal: z.string() }))),
  notes: nullable(z.array(z.string())),
  days: z.array(cfDaySchema),
});

export type ClaudeFitnessPlan = z.infer<typeof claudeFitnessPlanSchema>;

export function isClaudeFitnessPlan(value: unknown): boolean {
  return typeof value === "object" && value !== null && "schema_version" in value && "meal_slots" in value;
}

function slotType(id: string, label: string): MealTypeValue | undefined {
  const key = `${id} ${label}`.toLowerCase();
  if (/breakfast|colazione/.test(key)) return "breakfast";
  if (/lunch|pranzo/.test(key)) return "lunch";
  if (/dinner|cena/.test(key)) return "dinner";
  if (/snack|spuntino|merenda/.test(key)) return "snack";
  return undefined;
}

function toFood(item: z.infer<typeof cfItemSchema>): PlannedFood {
  const food: PlannedFood = { name: item.food };
  if (item.quantity != null) food.quantity = item.quantity;
  if (item.unit) food.unit = item.unit;
  // "Banana 1 pz (118 g)": show the weight when the unit is not already a weight or volume
  const weight = item.grams && item.unit && !/^(g|kg|ml|l)$/i.test(item.unit.trim()) ? `${item.grams} g` : undefined;
  const note = [weight, item.note?.trim()].filter(Boolean).join(" · ");
  if (note) food.note = note;
  return food;
}

function toMacros(macros: z.infer<typeof cfMacrosSchema>): PlannedMacros {
  const result: PlannedMacros = {
    kcal: macros.kcal,
    protein: macros.protein_g,
    carbs: macros.carbs_g,
    fat: macros.fat_g,
    fiber: macros.fiber_g,
  };
  if (macros.sugar_g != null) result.sugar = macros.sugar_g;
  if (macros.added_sugar_g != null) result.addedSugar = macros.added_sugar_g;
  if (macros.saturated_fat_g != null) result.saturatedFat = macros.saturated_fat_g;
  if (macros.sodium_mg != null) result.sodiumMg = macros.sodium_mg;
  if (macros.caffeine_mg != null) result.caffeineMg = macros.caffeine_mg;
  return result;
}

/** "Spuntino 11" → "Spuntino" (the time is shown separately). */
const slotTitle = (label: string) => label.replace(/\s+\d{1,2}([:.]\d{2})?$/, "").trim();

const FEMININE = /^(cena|colazione|merenda)/i;
const freeLabel = (title: string) => `${title.toLowerCase()} ${FEMININE.test(title) ? "libera" : "libero"}`;

/** Converts a Claude Fitness plan into Intake's MealPlan (not yet validated). */
export function convertClaudeFitnessPlan(source: ClaudeFitnessPlan): unknown {
  const globalFree = new Set((source.free_meals ?? []).map((f) => `${f.day}:${f.meal}`));
  const days: Partial<Record<(typeof WEEKDAYS)[number], PlannedDay>> = {};

  for (const day of source.days) {
    const meals: PlannedMeal[] = [];
    const noteParts: string[] = [];
    let hasFree = false;

    for (const slot of source.meal_slots) {
      const meal = day.meals[slot.id];
      if (!meal) continue;
      const type = slotType(slot.id, slot.label);
      let title = slotTitle(slot.label);
      const base = {
        title,
        ...(slot.time ? { time: slot.time } : {}),
        ...(type && (MEAL_TYPES as readonly string[]).includes(type) ? { type } : {}),
        ...(meal.description ? { description: meal.description.trim() } : {}),
      };

      const isFree = meal.free === true || day.free_meals?.includes(slot.id) || globalFree.has(`${day.day}:${slot.id}`) || meal.items.length === 0;
      if (isFree) {
        hasFree = true;
        noteParts.push(freeLabel(title));
        meals.push({ ...base, free: true });
        continue;
      }

      if (meal.sweet && type === "snack") title = `${title} dolce`;
      if (meal.family_friendly && type === "lunch") {
        title = `${title} in famiglia`;
        noteParts.unshift("pranzo in famiglia");
      }
      const foods = meal.items.map(toFood);
      if (meal.alternative && meal.alternative.length > 0) {
        foods.push({ name: `oppure: ${meal.alternative.map((item) => toFood(item)).map((f) => [f.name, f.quantity, f.unit].filter(Boolean).join(" ")).join(", ")}` });
      }
      meals.push({ ...base, title, foods, ...(meal.macros ? { macros: toMacros(meal.macros) } : {}) });
    }

    const label = day.tags?.includes("sweet_snack") ? "dolce" : hasFree ? "libero" : undefined;
    const note = day.note?.trim() || (noteParts.length > 0 ? noteParts.join(" · ") : undefined);
    days[day.day] = {
      ...(label ? { label } : {}),
      ...(note ? { note: note.slice(0, 80) } : {}),
      ...(day.expected_protein_g != null ? { expectedProtein: day.expected_protein_g } : {}),
      meals,
    };
  }

  return {
    schemaVersion: 1,
    validFrom: source.valid_from ?? source.updated,
    ...(source.notes && source.notes.length > 0 ? { notes: source.notes } : {}),
    days,
  };
}

export type PlanImportResult = { success: true; plan: MealPlan } | { success: false; issues: Array<{ path: string; message: string }> };

const toIssues = (error: z.ZodError) => error.issues.slice(0, 20).map((issue) => ({ path: issue.path.join("."), message: issue.message }));

/** Accepts either Intake's MealPlan or the Claude Fitness format, and returns a validated MealPlan. */
export function importPlan(value: unknown): PlanImportResult {
  if (isClaudeFitnessPlan(value)) {
    const source = claudeFitnessPlanSchema.safeParse(value);
    if (!source.success) return { success: false, issues: toIssues(source.error) };
    const missing = WEEKDAYS.filter((weekday) => !source.data.days.some((d) => d.day === weekday));
    if (missing.length > 0) return { success: false, issues: missing.map((weekday) => ({ path: "days", message: `missing ${weekday}` })) };
    const converted = mealPlanSchema.safeParse(convertClaudeFitnessPlan(source.data));
    return converted.success ? { success: true, plan: converted.data } : { success: false, issues: toIssues(converted.error) };
  }
  const plan = mealPlanSchema.safeParse(value);
  return plan.success ? { success: true, plan: plan.data } : { success: false, issues: toIssues(plan.error) };
}
